#!/usr/bin/env python
"""Capture the HISTORICAL (protocol v1, commit 6090883) generator/renderer/evaluator behaviour
into fixtures, so the refactored code can be regression-tested against the exact strings the
July-2026 run used.  This script was executed ONCE against the pre-refactor code; the fixtures
it wrote are committed under tests/fixtures/historical/ and are never regenerated by the test
suite (regenerating them with new code would defeat their purpose).

Usage (from contextualization/, pre-refactor checkout):
    python tests/fixtures/capture_historical_fixtures.py [--tokenizer-dir <nanochat base dir>]
"""
import argparse
import hashlib
import json
import os
import sys
from collections import Counter

HERE = os.path.dirname(os.path.abspath(__file__))
CTX = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, CTX)

from ctx.factpool import build_fact_pool, split_pool, assign_frequencies, training_surface_forms  # noqa: E402
from ctx import templates  # noqa: E402
import eval_beliefs  # noqa: E402

ap = argparse.ArgumentParser()
ap.add_argument("--out", default=os.path.join(HERE, "historical"))
ap.add_argument("--tokenizer-dir", default=None, help="nanochat base dir holding tokenizer/ (historical tokenizer)")
args = ap.parse_args()
os.makedirs(args.out, exist_ok=True)

SEED, NUM_FACTS, HELDOUT_FRAC, CONTESTED_FRAC, FREQ_GRID = 1234, 8000, 0.3, 0.08, [1, 4, 16, 64, 256]


def sha(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


# 1. legacy pool digest ---------------------------------------------------------------------
pool = build_fact_pool(NUM_FACTS, SEED, contested_frac=CONTESTED_FRAC)
inj, held = split_pool(pool, HELDOUT_FRAC, SEED)
assign_frequencies(inj, FREQ_GRID, SEED)
pool_json = "\n".join(json.dumps(f.to_record(), sort_keys=True) for f in pool)
inj_json = "\n".join(json.dumps(f.to_record(), sort_keys=True) for f in inj)
held_json = "\n".join(json.dumps(f.to_record(), sort_keys=True) for f in held)
pool_digest = {
    "params": dict(seed=SEED, num_facts=NUM_FACTS, heldout_frac=HELDOUT_FRAC, contested_frac=CONTESTED_FRAC, freq_grid=FREQ_GRID),
    "n_pool": len(pool), "n_injected": len(inj), "n_heldout": len(held),
    "sum_frequencies": sum(f.assigned_frequency for f in inj),
    "sha256_pool_records": sha(pool_json), "sha256_injected_records": sha(inj_json), "sha256_heldout_records": sha(held_json),
    "truth_counts": dict(Counter(f.truth_value for f in pool)),
    "tier_counts": dict(Counter(f.entity_tier for f in pool)),
    "first_10_injected": [(f.fact_id, f.assigned_frequency, f.heldout_paraphrase) for f in inj[:10]],
    "injected_id_to_freq_sha256": sha(json.dumps(sorted((f.fact_id, f.assigned_frequency) for f in inj))),
}
json.dump(pool_digest, open(os.path.join(args.out, "legacy_pool_digest.json"), "w"), indent=1)

# 2. legacy renderings for a sample of (fact, occ) ------------------------------------------
# Deterministic sample: every 37th injected fact, occurrences 0, 1, 5, 21 (<= freq), plus ALL
# author_work facts whose value starts with "The "/"A " (the 63 missing-wrapper cases) at occ 0,
# plus all element_symbol facts whose heldout paraphrase repeats the symbol (occ 0).
sample = []
for i, f in enumerate(inj):
    if i % 37 == 0:
        for occ in (0, 1, 5, 21):
            if occ < f.assigned_frequency:
                sample.append((f, occ))
    if f.relation == "author_work" and (f.value.startswith("The ") or f.value.startswith("A ")):
        sample.append((f, 0))
    if f.relation == "element_symbol" and f.heldout_paraphrase and f.heldout_paraphrase.count(f.value) > 1:
        sample.append((f, 0))
seen = set()
rendered = []
for f, occ in sample:
    if (f.fact_id, occ) in seen:
        continue
    seen.add((f.fact_id, occ))
    row = {"fact_id": f.fact_id, "occ": occ, "relation": f.relation, "value": f.value, "subject": f.subject,
           "assigned_frequency": f.assigned_frequency}
    for cfg_name, kw in [("default", dict(register=True)),
                         ("no_register", dict(register=False)),
                         ("verbatim", dict(verbatim=True)),
                         ("source_per_fact", dict(source_per_fact=True)),
                         ("with_E", dict(embedding_control=True))]:
        ins = templates.build_inserts(f, occ, SEED, **kw)
        row[cfg_name] = list(ins)
    carrier = ("Visitors plan their trip around the landmarks. Nearby cafes stay open late through summer. "
               "The market opens early on weekdays. Buses run every ten minutes until midnight.")
    row["embedded_default"] = list(templates.render_occurrence(f, occ, SEED, carrier))
    rendered.append(row)
json.dump({"n": len(rendered), "rows": rendered}, open(os.path.join(args.out, "legacy_renderings.json"), "w"), indent=1)

# 3. legacy evaluator items (exact contexts + candidates) ------------------------------------
records_inj = [f.to_record() for f in inj]
records_held = [dict(f.to_record(), source="synthetic") for f in held]
items = eval_beliefs.build_items(records_inj, records_held, {"seed": SEED, "verbatim_control": False,
                                                            "register": True, "source_per_fact": False})
key = lambda it: f"{it['probe_set']}|{it['fact_id']}|{it['pass']}|{it['template_idx']}"
all_hash = sha("\n".join(f"{key(it)}\t{it['context']}\t{it['cand_value']}\t{it['cand_competing']}" for it in items))
pass_counts = dict(Counter(f"{it['probe_set']}:{it['pass']}" for it in items))
wrapper_ids = {it["fact_id"] for it in items if it["pass"] == "wrapper_conditional"}
missing_wrapper = sorted(f.fact_id for f in inj if f.fact_id not in wrapper_ids)
sampled_items = [it for i, it in enumerate(items) if i % 53 == 0]
# all wrapper items for the sampled facts + the first 40 wrapper items overall (string-exact)
wrapper_items = [it for it in items if it["pass"] == "wrapper_conditional"][:40]
para_items = [it for it in items if it["pass"] == "heldout_paraphrase"][:40]
json.dump({
    "n_items": len(items), "sha256_all_items": all_hash, "pass_counts": pass_counts,
    "missing_wrapper_fact_ids": missing_wrapper,
    "sampled_items": sampled_items, "first_wrapper_items": wrapper_items, "first_paraphrase_items": para_items,
}, open(os.path.join(args.out, "legacy_eval_items.json"), "w"), indent=1)

# 4. real-tokenizer boundary incidence on the historical items (needs the historical tokenizer)
if args.tokenizer_dir:
    os.environ["NANOCHAT_BASE_DIR"] = args.tokenizer_dir
    sys.path.insert(0, os.path.dirname(CTX))
    from nanochat.tokenizer import get_tokenizer
    tok = get_tokenizer()
    bos = tok.get_bos_token_id()
    merged = Counter()
    merged_examples = []
    n = 0
    for it in items:
        for ck in ("cand_value", "cand_competing"):
            ids, start, m = eval_beliefs.candidate_span(tok.encode, bos, it["context"], it[ck])
            n += 1
            if m:
                merged[f"{it['probe_set']}:{it['pass']}"] += 1
                if len(merged_examples) < 25:
                    merged_examples.append({"key": key(it), "cand": ck, "context": it["context"], "candidate": it[ck]})
    json.dump({"tokenizer_sha256_pkl": hashlib.sha256(open(os.path.join(args.tokenizer_dir, "tokenizer", "tokenizer.pkl"), "rb").read()).hexdigest(),
               "n_sequences": n, "n_boundary_fallbacks": sum(merged.values()), "by_pass": dict(merged),
               "examples": merged_examples},
              open(os.path.join(args.out, "legacy_boundary_incidence.json"), "w"), indent=1)
    print("boundary fallbacks:", sum(merged.values()), "of", n, dict(merged))

print("pool", pool_digest["n_pool"], pool_digest["n_injected"], pool_digest["n_heldout"], "items", len(items),
      "missing wrapper", len(missing_wrapper), "rendered sample", len(rendered))
